        setPrivateField(fitnessFunction, "boundaries", null);
        setPrivateField(fitnessFunction, "isRepairMode", false);
        setPrivateField(fitnessFunction, "isMinimize", true);

        // Mocking the behavior of the inner class's access to the outer class
        // The method calls CMAESOptimizer.this.computeObjectiveValue(decode(point))
        // Because FitnessFunction is an inner class, we simulate the 'this' context
        // via the spy and the mocked method calls.

