        double[] point = {1.0, 2.0};
        double[] repaired = {1.5, 2.5};
        double[] decoded = {1.5, 2.5};
        double objectiveValue = 20.0;
        double penaltyValue = 5.0;

        FitnessFunction ff = spy(new FitnessFunction());
