        setPrivateField(ff, "boundaries", new double[]{0.0});
        setPrivateField(ff, "isRepairMode", true);
        setPrivateField(ff, "isMinimize", false);

        when(ff.repair(point)).thenReturn(repaired);
        when(ff.decode(repaired)).thenReturn(decoded);
