    // Helper to set private fields for testing purposes
    private void setPrivateField(Object target, String fieldName, Object value) {
        try {
            java.lang.reflect.Field field = target.getClass().getDeclaredField(fieldName);
            field.setAccessible(true);
            field.set(target, value);
        } catch (Exception e) {
            // In a real scenario, if the field is in the outer class, 
            // we would need to access the outer class field.
            // Since FitnessFunction is an inner class, 'boundaries' etc. 
            // are likely fields of the outer class or the inner class itself.
            try {
                java.lang.reflect.Field field = target.getClass().getSuperclass().getDeclaredField(fieldName);
                field.setAccessible(true);
                field.set(target, value);
            } catch (Exception ex) {
